el>Business expenses<input type="number" min="0" name="business_expenses" value="0"></label><label>Household expenses<input type="number" min="0" name="household_expenses" value="0"></label></div><div class="form-actions"><button class="btn btn-primary">Create draft application</button></div></div></form>
@push('scripts')<script>const p=document.getElementById('product'),a=document.getElementById('amount'),m=document.getElementById('months'),e=document.getElementById('estimate');function calc(){let o=p.selectedOptions[0],principal=+a.value,months=+m.value;if(!o?.dataset.rate||!principal||!months){e.value='';return}a.min=o.dataset.min;a.max=o.dataset.max;m.min=o.dataset.minmonths;m.max=o.dataset.maxmonths;let interest=principal*(+o.dataset.rate/100)*(months/12);e.value='TZS '+Math.round(principal+interest).toLocaleString()}[p,a,m].forEach(x=>x.addEventListener('input',calc));</script>@endpush
